using System;using Recovered.Animation;namespace Recovered.Gameplay {public static class PtlAttachmentRetirement {
  struct N {
   PlaybackWide v;bool neg;bool Zero{get{return v.StoreDouble()==0;}}
   N(PlaybackWide x,bool sign){v=x;double d=x.StoreDouble();neg=d<0||(d==0&&sign);}
   public static N Word(uint w){return new N(PlaybackWide.From(F(w)),(w&0x80000000)!=0);}
   public static N Tenth(){return new N(PlaybackWide.FromDouble(0.1),false);}
   public static N Integer(int i){return new N(PlaybackWide.FromDouble(i),i<0);}
   public static N Add(N a,N b){return new N(PlaybackWide.Add(a.v,b.v),a.Zero&&b.Zero&&a.neg&&b.neg);}
   public static N Sub(N a,N b){return Add(a,new N(PlaybackWide.Multiply(b.v,PlaybackWide.FromDouble(-1)),!b.neg));}
   public static N Mul(N a,N b){return new N(PlaybackWide.Multiply(a.v,b.v),a.neg!=b.neg);}
   public uint Store(){uint w=BitConverter.ToUInt32(BitConverter.GetBytes(v.Store()),0);return Zero&&neg?w|0x80000000:w;}
  }
  static float F(uint w){return BitConverter.ToSingle(BitConverter.GetBytes(w),0);}
static int H(SoundSetupImage m,uint at){return unchecked((short)m.Half(at));}static uint Owner(SoundSetupImage m,uint node){return m.Word(node+12);}static void AddHalf(SoundSetupImage m,uint at,int amount){m.Half(at,unchecked((ushort)(m.Half(at)+amount)));}public static void Retire(SoundSetupImage m,uint node,uint head){unchecked{uint owner=Owner(m,node);int physical=H(m,owner+0x182);uint record=m.Word(m.Word(0x296209c)+(uint)physical*4);int count=H(m,owner+0x180),selected=0;if(count>0){uint chunk=m.Word(node),cursor=owner+0x100;for(int i=0;i<H(m,Owner(m,node)+0x180);i++,cursor+=4)if(m.Word(cursor)==chunk){selected=i;break;}}int index=selected;if(index<count-1){uint offset=(uint)selected*4+0x100;while(index<H(m,Owner(m,node)+0x180)-1){owner=Owner(m,node);m.Word(owner+offset,m.Word(owner+offset+4));index++;offset+=4;}}owner=Owner(m,node);m.Word(owner+0xfc+(uint)H(m,owner+0x180)*4,0);AddHalf(m,Owner(m,node)+0x180,-1);AddHalf(m,Owner(m,node)+0x18c,-1);AddHalf(m,Owner(m,node)+0x188,-1);owner=Owner(m,node);if(H(m,owner+0x180)<=0){m.Half(owner+0x186,0);m.Half(Owner(m,node)+0x18e,0);}else {int unit=m.Byte(record+0x2e)==7?12:32;AddHalf(m,owner+0x186,-unit);AddHalf(m,Owner(m,node)+0x18e,-unit);owner=Owner(m,node);if(H(m,owner+0x18a)>(selected+1)*unit)AddHalf(m,owner+0x18a,-unit);}owner=Owner(m,node);if(H(m,owner+0x180)>0)PtlParticleLinks.Commands(m,owner+0x100,H(m,owner+0x180));else {for(uint i=0;i<8;i++){uint at=record+0x3d0+i*2;ushort id=m.Half(at);if(id!=65535&&m.Word(0x29620a4)+unchecked((uint)(short)id)*0x330==Owner(m,node)){m.Half(Owner(m,node)+0x182,0);m.Half(Owner(m,node)+0x32a,65535);uint cursor=m.Word(0x29211e8),fifo=m.Word(0x2962084);cursor--;m.Word(0x29211e8,cursor);m.Half(fifo+cursor*2,m.Half(at));m.Half(at,65535);}}m.Word(Owner(m,node)+0x100,0);}if(selected==0){int capacity=unchecked((int)(m.Word(0x8108e8)+m.Word(0x8108ec)));if(capacity>0){uint packets=m.Word(0x2961fec),chunk=m.Word(node);for(int i=0;i<capacity;i++){uint packet=packets+(uint)i*100;if(m.Word(packet)==chunk){uint offset=(uint)i*100;m.Word(packet,m.Word(Owner(m,node)+0x100));if(H(m,Owner(m,node)+0x180)==0){int bank=unchecked((sbyte)m.Byte(record+0x2f1));PtlParticleUnlinks.Priority(m,m.Word(0x2961fec)+offset,0x292fd30+(uint)bank*4);m.Word(m.Word(0x2961fec)+offset+4,0);m.Word(m.Word(0x2961fec)+offset+8,0);}break;}}}}m.Word(node+4,N.Add(N.Word(m.Word(node+4)),N.Tenth()).Store());m.Word(node+8,m.Byte(record+0x2e)==7?9U:2U);PtlParticleLinks.Timed(m,node,head);}}public static void Process(SoundSetupImage m,int bank,Action<SoundSetupImage,uint,uint> bounce){PtlTimedReturns.Process(m,bank,delegate(SoundSetupImage image,uint node,uint head){if(image.Word(node+8)==1)Retire(image,node,head);else if(bounce!=null)bounce(image,node,head);else throw new ArgumentException("Explicit bounce branch required.");});}}}
